using System.Text.Json;
using Microsoft.Web.WebView2.WinForms;
namespace DshLauncher;
internal static class WebModalRouter
{
    public static void Open(WebView2 web, AppSettings s, string page)
    {
        var data = new { page, version = VersionHelper.Current, attachPort = s.AttachPort, workingDirectory = s.WorkingDirectory,
            manager = new { s.Manager.Enabled, s.Manager.ServerUrl, s.Manager.AgentName, s.Manager.PairingCode, s.Manager.ServerCertificateFingerprint },
            closeExits = s.CloseExits, autoStart = s.AutoStart,
            ssh = s.SshConnections.Select(x => new { x.Name, x.Host, x.Port, x.User, x.AuthMethod, x.KeyPath, x.LocalPort, x.RemotePort, x.AutoConnect }),
            history = "", plugins = Array.Empty<object>() };
        Open(web, page, data);
    }
    public static void Open(WebView2 web, string page, object? data = null)
    {
        var cwv = web.CoreWebView2; if (cwv == null) { Diag.Log($"WebModalRouter.Open skipped page={page}: CoreWebView2 is null"); return; }
        var json = JsonSerializer.Serialize(data ?? new { page }); var payload = JsonSerializer.Serialize(json);
        var script = "(function(){try{document.getElementById('dsh-modal')?.remove();if(!window.__dshModal){" + Script + "}window.__dshModal(" + payload + ");}catch(e){document.body.setAttribute('data-dsh-modal-error',String(e));throw e;}})();";
        _ = cwv.ExecuteScriptAsync(script);
    }
    public static async Task Install(WebView2 web) { if (web.CoreWebView2 != null) await web.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync(Script); }
    public static bool TryHandle(string raw, Action<string, JsonElement> action) { try { using var d = JsonDocument.Parse(raw); var r = d.RootElement; if (!string.Equals(Prop(r,"type").GetString(), "modal", StringComparison.OrdinalIgnoreCase)) return false; action(Prop(r,"action").GetString() ?? "", r.TryGetProperty("payload", out var p) ? p : default); return true; } catch { return false; } }
    private static JsonElement Prop(JsonElement o, string name) { foreach (var p in o.EnumerateObject()) if (p.Name.Equals(name, StringComparison.OrdinalIgnoreCase)) return p.Value; return default; }
    public static void Apply(AppSettings s, JsonElement d)
    {
        var p=Prop(d,"attachPort"); if(p.TryGetInt32(out var port)) s.AttachPort=port; var w=Prop(d,"workingDirectory"); if(w.ValueKind==JsonValueKind.String) s.WorkingDirectory=w.GetString();
        var ce=Prop(d,"closeExits"); if(ce.ValueKind is JsonValueKind.True or JsonValueKind.False)s.CloseExits=ce.GetBoolean(); var ast=Prop(d,"autoStart"); if(ast.ValueKind is JsonValueKind.True or JsonValueKind.False)s.AutoStart=ast.GetBoolean();
        var m=Prop(d,"manager"); if(m.ValueKind==JsonValueKind.Object){var v=Prop(m,"enabled");if(v.ValueKind is JsonValueKind.True or JsonValueKind.False)s.Manager.Enabled=v.GetBoolean(); s.Manager.ServerUrl=Str(m,"serverUrl");s.Manager.AgentName=Str(m,"agentName");s.Manager.PairingCode=Str(m,"pairingCode");s.Manager.ServerCertificateFingerprint=Str(m,"serverCertificateFingerprint");} s.Save();s.ApplyAutoStart();
    }
    private static string Str(JsonElement o,string n) => (Prop(o,n).ValueKind==JsonValueKind.String ? Prop(o,n).GetString() : null) ?? "";
    private const string Script = """
(function(){if(window.__dshModal)return;var zh=(navigator.language||'').toLowerCase().indexOf('zh')===0;var t=function(c,e){return zh?c:e};var send=function(a,p){chrome.webview.postMessage(JSON.stringify({type:'modal',action:a,payload:p||{}}));},esc=function(x){return String(x??'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
