else if(page==='plugins')body='<div class=toolbar><input id=pkg placeholder="'+t('包名','Package')+'"><button class=primary id=install>'+t('添加','Install')+'</button><button id=remove>'+t('移除选中','Remove selected')+'</button><button id=update>'+t('更新选中','Update selected')+'</button><button id=list>'+t('刷新','Refresh')+'</button></div><div class=plugin-grid id=plist>'+(m.plugins||[]).map(function(x){var p=x.package||x.Package||'',spec=x.spec||x.Spec||'',kind=(x.isBundle||x.IsBundle)?'bundle':((x.isTemplate||x.IsTemplate)?'template':'plugin');return '<article class=plugin-row data-pkg="'+esc(p)+'"><button class=plugin-select type=button><b>'+esc(p)+'</b><small>'+esc(kind)+' · '+esc(spec||''+t('未指定版本','unspecified')+'')+'</small></button></article>'}).join('')+'</div>';
else if(page==='logs')body='<textarea id=logbox readonly>'+esc(m.history||'')+'</textarea><div class=actions><button id=clear>'+t('清空','Clear')+'</button></div>';else if(page==='folder')body='<div class=form-row><label>'+t('路径','Path')+'</label><input id=path placeholder="/home/user/workspace" value="'+esc(m.path||'')+'"></div><div class=actions><button class=primary id=select>'+t('列出子目录','List')+'</button><button id=create>'+t('创建并添加','Create')+'</button></div><pre id=dirs>'+esc((m.dirs||[]).join('\n'))+'</pre>';else if(page==='ssh')body='<div class=actions><button class=primary id=add>'+t('新增 SSH','Add SSH')+'</button></div><div class=items>'+(m.ssh||[]).map(function(x){var n=x.name||x.Name;return '<div class=item><div><b>'+esc(n)+'</b><span>'+esc((x.user||x.User)+'@'+(x.host||x.Host))+':'+(x.port||x.Port)+'</span></div><div><button data-edit="'+esc(n)+'">'+t('编辑','Edit')+'</button><button data-del="'+esc(n)+'">'+t('删除','Delete')+'</button><button class=primary data-connect="'+esc(n)+'">'+t('连接','Connect')+'</button></div></div>'}).join('')+'</div>';else body='<div class=about><strong>DshLauncher</strong><span>'+t('版本','Version')+' '+esc(m.version||'')+'</span></div>';
var o=document.createElement('div');o.id='dsh-modal';o.innerHTML='<div class=backdrop></div><section class=card role=dialog aria-modal=true aria-labelledby=dsh-modal-title><header class=modal-header><div><p class=eyebrow>DshLauncher</p><h2 id=dsh-modal-title>'+titles[page]+'</h2></div><button class=close id=x aria-label='+t('关闭','Close')+'>×</button></header><main class=modal-main>'+body+'</main><footer class=modal-footer><button id=cancel>'+t(''+t('关闭','Close')+'','Close')+'</button></footer></section>';document.body.appendChild(o);var st=document.createElement('style');st.textContent='#dsh-modal{--dsh-launcher-bg:#202225;--dsh-launcher-fg:#f4f4f5;--dsh-launcher-accent:#70a5ff;position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;font:14px/1.45 Segoe UI,sans-serif;color:var(--dsh-launcher-fg)}#dsh-modal *{box-sizing:border-box}#dsh-modal .backdrop{position:absolute;inset:0;background:rgba(0,0,0,.58)}#dsh-modal .card{position:relative;width:min(680px,calc(100vw - 32px));max-height:min(88vh,760px);overflow:auto;background:var(--dsh-launcher-bg);border:1px solid rgba(255,255,255,.14);border-radius:12px;box-shadow:0 24px 80px rgba(0,0,0,.42);padding:0}#dsh-modal .modal-header{display:flex;align-items:flex-start;justify-content:space-between;padding:18px 20px 14px;border-bottom:1px solid rgba(255,255,255,.1)}#dsh-modal .eyebrow{margin:0 0 2px;color:var(--dsh-launcher-accent);font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase}#dsh-modal h2{margin:0;font-size:20px;font-weight:650}#dsh-modal .close{margin:0;padding:2px 8px;border:0;background:transparent;color:inherit;font-size:24px;line-height:1;cursor:pointer}#dsh-modal .close:hover{color:var(--dsh-launcher-accent)}#dsh-modal .modal-main{padding:16px 20px}#dsh-modal fieldset{margin:0 0 12px;padding:12px 14px;border:1px solid rgba(255,255,255,.14);border-radius:9px}#dsh-modal legend{padding:0 6px;color:var(--dsh-launcher-accent);font-weight:600}#dsh-modal .form-row{display:grid;grid-template-columns:minmax(150px,190px) minmax(0,1fr);align-items:center;gap:12px;margin:9px 0}#dsh-modal input,#dsh-modal textarea{width:100%;border:1px solid rgba(255,255,255,.18);border-radius:6px;background:rgba(0,0,0,.16);color:inherit;padding:8px 9px}#dsh-modal input[type=checkbox]{width:auto;accent-color:var(--dsh-launcher-accent)}#dsh-modal button{border:1px solid rgba(255,255,255,.16);border-radius:6px;background:rgba(255,255,255,.07);color:inherit;padding:7px 11px;cursor:pointer}#dsh-modal button:hover{border-color:var(--dsh-launcher-accent);background:rgba(112,165,255,.14)}#dsh-modal button.primary{border-color:var(--dsh-launcher-accent);background:var(--dsh-launcher-accent);color:#111827}#dsh-modal .actions,#dsh-modal .toolbar{display:flex;flex-wrap:wrap;gap:6px;align-items:center}#dsh-modal .toolbar{margin-bottom:12px}#dsh-modal .plugin-row,#dsh-modal .item{margin:8px 0;padding:10px;border:1px solid rgba(255,255,255,.12);border-radius:8px}#dsh-modal .plugin-row.selected{border-color:var(--dsh-launcher-accent);background:rgba(112,165,255,.14)}#dsh-modal .plugin-select{display:flex;width:100%;justify-content:space-between;text-align:left;border:0;background:transparent}#dsh-modal .plugin-select small,#dsh-modal .item span{display:block;color:rgba(244,244,245,.68)}#dsh-modal .item{display:flex;justify-content:space-between;gap:12px;align-items:center}#dsh-modal #logbox{min-height:280px;resize:vertical;font:12px/1.5 Consolas,monospace}#dsh-modal pre{max-height:220px;overflow:auto;padding:10px;border-radius:7px;background:rgba(0,0,0,.18)}#dsh-modal .modal-footer{display:flex;justify-content:flex-end;padding:12px 20px 16px;border-top:1px solid rgba(255,255,255,.1)}@media(max-width:560px){#dsh-modal .card{width:calc(100vw - 20px);max-height:92vh}#dsh-modal .modal-main{padding:12px}#dsh-modal .form-row{grid-template-columns:1fr;gap:5px}#dsh-modal .item{align-items:stretch;flex-direction:column}}';o.appendChild(st);var val=function(id){return o.querySelector('#'+id)?.value||''};o.onclick=function(e){var t=e.target, row=t.closest?.('.plugin-row');if(t.id==='x'||t.id==='cancel'||t.classList.contains('backdrop'))o.remove();else if(t.id==='save')send('settings.save',{attachPort:+val('port'),workingDirectory:val('wd'),closeExits:o.querySelector('#ce').checked,autoStart:o.querySelector('#as').checked,manager:{enabled:o.querySelector('#men').checked,serverUrl:val('url'),agentName:val('an'),pairingCode:val('pc'),serverCertificateFingerprint:val('fp')}});else if(row){window.__dshSelectedPlugin=row.dataset.pkg;o.querySelectorAll('.plugin-row').forEach(x=>x.classList.toggle('selected',x===row));}else if(t.id==='install')send('plugins.install',{package:val('pkg')});else if(t.id==='remove')send('plugins.remove',{package:window.__dshSelectedPlugin||val('pkg')});else if(t.id==='update')send('plugins.update',{package:window.__dshSelectedPlugin||val('pkg')});else if(t.id==='list')send('plugins.list');else if(t.id==='clear')send('logs.clear');else if(t.id==='select')send('folder.list',{path:val('path')});else if(t.id==='create')send('folder.create',{path:val('path')});else if(t.id==='add'){var n=prompt(''+t('名称','Name')+'','');if(n===null)return;var h=prompt(''+t('主机','Host')+'','');if(h===null)return;var u=prompt(''+t('用户名','User')+'','');if(u===null)return;if(h&&u)send('ssh.add',{name:n||u+'@'+h,host:h,port:22,user:u,authMethod:'key',keyPath:''});}else if(t.dataset.edit)send('ssh.edit',{name:t.dataset.edit});else if(t.dataset.del)send('ssh.delete',{name:t.dataset.del});else if(t.dataset.connect)send('ssh.connect',{name:t.dataset.connect});};};
})();
""";
